// Ansambluri active (la vanzare, in constructie sau promotie)
export const ANSAMBLURI_ACTIVE = ANSAMBLURI.filter(a =>
  ['activ', 'constructie', 'promotie', 'finalizat'].includes(a.status)
)

// Versiune lightweight pentru homepage si componente client
// Exclude campurile grele (descriereCompleta ~69KB, apartamente, dotari, puncteInteres)
// Reduce bundle-ul client cu ~75%
export const ANSAMBLURI_LITE = ANSAMBLURI_ACTIVE.map(({
  descriereCompleta, dotari, puncteInteres, parcare,
  apartamente,
  ...rest
}) => ({
  ...rest,
  _hasPromo: Array.isArray(apartamente) && apartamente.some(apt => apt.promo === true),
}))

// Ansambluri portofoliu (vandute)
export const ANSAMBLURI_PORTOFOLIU = ANSAMBLURI.filter(a => a.status === 'vandut')

// Helper: gaseste ansamblu dupa slug
export function getAnsamblu(slug) {
  return ANSAMBLURI.find(a => a.slug === slug) || null
}

// Helper: formatare pret
// Returneaza true daca ansamblul are cel putin un apartament cu promo: true
// Folosit pentru badge si filtru Promotie fara a atinge campul status
export function hasPromo(a) {
  return Array.isArray(a.apartamente) && a.apartamente.some(apt => apt.promo === true)
}

export function formatPret(pret) {
  return new Intl.NumberFormat('ro-RO').format(pret) + '\u20ac'
}

// Culori badge per status
